const oldFile = {
  contents: [
    "export function greet(name: string) {",
    `  return \`Hello, \${name}\`;`,
    "}",
    "",
  ].join("\n"),
  name: "greeting.ts",
};

const newFile = {
  contents: [
    'export function greet(name: string = "world") {',
    `  const greeting = \`Welcome, \${name}!\`;`,
    "  return greeting;",
    "}",
    "",
  ].join("\n"),
  name: "greeting.ts",
};

export { oldFile, newFile };

import { useState } from "react";
import { DiffView } from "@/registry/erbium/blocks/diff-view";
import { Button } from "@/registry/erbium/ui/button";
import { oldFile, newFile } from "../examples/files";

export default function DiffViewChangingSourceExample() {
  const [reversed, setReversed] = useState(false);

  return (
    <div className="grid w-full gap-4">
      <Button
        className="w-fit"
        size="sm"
        variant="outline"
        onClick={() => {
          setReversed(!reversed);
        }}
      >
        Swap file versions
      </Button>
      <DiffView oldFile={reversed ? newFile : oldFile} newFile={reversed ? oldFile : newFile} />
    </div>
  );
}
